-- =============================================================================
-- KaiXu PostgreSQL 16 schema (design baseline v1.0)
-- Apply to an EMPTY database. Forward-only migrations live in services/api later.
-- Conventions:
--   * IDs are UUIDv7 generated by the application (gen_random_uuid is a fallback).
--   * All timestamps are timestamptz; business display timezone is Asia/Shanghai.
--   * Every shared/business row carries version for optimistic concurrency.
--   * Private data is separated into owner-scoped tables/columns and never
--     projected by shared read models.
-- =============================================================================

create extension if not exists pgcrypto;
create extension if not exists citext;
create extension if not exists pg_trgm;
create extension if not exists btree_gist;

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------
create type user_status as enum ('ACTIVE', 'DISABLED', 'DELETED');
create type workspace_kind as enum ('COURSE', 'PROJECT');
create type workspace_visibility as enum ('PERSONAL', 'SHARED');
create type workspace_status as enum ('ACTIVE', 'ARCHIVED');
create type member_role as enum ('OWNER', 'MEMBER');
create type member_status as enum ('ACTIVE', 'LEFT', 'REMOVED');
create type transfer_status as enum ('PENDING', 'ACCEPTED', 'DECLINED', 'CANCELLED');
create type task_status as enum ('TODO', 'IN_PROGRESS', 'COMPLETED');
create type task_priority as enum ('LOW', 'MEDIUM', 'HIGH', 'URGENT');
create type session_status as enum ('PLANNED', 'COMPLETED', 'CANCELLED');
create type resource_kind as enum ('LINK', 'TEXT', 'ATTACHMENT');
create type source_type as enum ('CANVAS', 'WECHAT', 'QQ', 'MANUAL', 'TIMETABLE');
create type source_status as enum ('CONNECTED', 'PAUSED', 'REVOKED', 'ERROR');
create type source_record_status as enum ('ACTIVE', 'WITHDRAWN', 'UNKNOWN');
create type candidate_type as enum ('NEW', 'FIELD_CHANGE', 'SUSPECTED_DUPLICATE');
create type candidate_status as enum ('PENDING', 'ACCEPTED', 'IGNORED', 'SUPERSEDED', 'NEEDS_REVIEW');
create type field_decision as enum ('PENDING', 'ACCEPT', 'REJECT');
create type focus_status as enum ('ACTIVE', 'PAUSED', 'COMPLETED', 'CANCELLED', 'INTERRUPTED');
create type focus_result as enum ('PENDING', 'MET', 'NOT_MET', 'INTERRUPTED');
create type segment_kind as enum ('FOREGROUND', 'BACKGROUND');
create type sync_status as enum ('APPLIED', 'REJECTED', 'CONFLICT');
create type change_op as enum ('UPSERT', 'DELETE');
create type outbox_status as enum ('PENDING', 'PUBLISHED', 'FAILED');
create type reminder_status as enum ('PENDING', 'SENT', 'FAILED', 'CANCELLED');

-- -----------------------------------------------------------------------------
-- Shared trigger functions
-- -----------------------------------------------------------------------------
create or replace function set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create or replace function bump_version()
returns trigger
language plpgsql
as $$
begin
  new.version = old.version + 1;
  new.updated_at = now();
  return new;
end;
$$;

-- A task may not move between workspaces after creation (FR-T02 / current release).
create or replace function forbid_task_workspace_change()
returns trigger
language plpgsql
as $$
begin
  if new.workspace_id is distinct from old.workspace_id then
    raise exception 'TASK_WORKSPACE_IMMUTABLE' using errcode = '23514';
  end if;
  return new;
end;
$$;

-- Stage dependencies must reference stages of the same task and cannot self-depend.
create or replace function check_stage_dependency()
returns trigger
language plpgsql
as $$
declare
  pred_task uuid;
  succ_task uuid;
begin
  if new.predecessor_stage_id = new.successor_stage_id then
    raise exception 'STAGE_DEPENDENCY_SELF' using errcode = '23514';
  end if;
  select task_id into pred_task from task_stage where id = new.predecessor_stage_id;
  select task_id into succ_task from task_stage where id = new.successor_stage_id;
  if pred_task is null or succ_task is null or pred_task <> succ_task or pred_task <> new.task_id then
    raise exception 'STAGE_DEPENDENCY_TASK_MISMATCH' using errcode = '23514';
  end if;
  return new;
end;
$$;

-- A task link may only reference a resource in the same workspace (BR10).
create or replace function check_resource_task_link_workspace()
returns trigger
language plpgsql
as $$
declare
  task_ws uuid;
  resource_ws uuid;
begin
  select workspace_id into task_ws from task where id = new.task_id;
  select workspace_id into resource_ws from resource where id = new.resource_id;
  if task_ws is null or resource_ws is null or task_ws <> resource_ws then
    raise exception 'RESOURCE_WORKSPACE_MISMATCH' using errcode = '23514';
  end if;
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Identity
-- -----------------------------------------------------------------------------
create table app_user (
  id uuid primary key default gen_random_uuid(),
  email citext not null unique,
  password_hash text not null,
  display_name varchar(80) not null,
  status user_status not null default 'ACTIVE',
  locale varchar(16) not null default 'zh-CN',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  last_login_at timestamptz,
  constraint app_user_email_not_blank check (length(btrim(email::text)) > 3),
  constraint app_user_display_name_not_blank check (length(btrim(display_name)) > 0)
);
create trigger trg_app_user_updated before update on app_user
for each row execute function set_updated_at();

create table user_settings (
  user_id uuid primary key references app_user(id) on delete cascade,
  timezone text not null default 'Asia/Shanghai',
  week_starts_on smallint not null default 1,
  default_focus_minutes integer not null default 25,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint user_settings_week_start check (week_starts_on between 1 and 7),
  constraint user_settings_focus_minutes check (default_focus_minutes between 1 and 240)
);
create trigger trg_user_settings_updated before update on user_settings
for each row execute function set_updated_at();

create table device (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references app_user(id) on delete cascade,
  platform varchar(16) not null,
  name varchar(120) not null default '',
  app_version varchar(40) not null default '',
  last_seen_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  constraint device_platform check (platform in ('WINDOWS', 'MACOS', 'ANDROID'))
);
create index idx_device_user on device(user_id, last_seen_at desc);

create table refresh_session (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references app_user(id) on delete cascade,
  device_id uuid references device(id) on delete set null,
  token_hash bytea not null unique,
  issued_at timestamptz not null default now(),
  expires_at timestamptz not null,
  revoked_at timestamptz,
  rotated_from uuid references refresh_session(id) on delete set null,
  last_used_at timestamptz,
  ip inet,
  user_agent text not null default '',
  constraint refresh_session_expiry check (expires_at > issued_at),
  constraint refresh_session_token_hash_len check (octet_length(token_hash) = 32)
);
create index idx_refresh_session_user on refresh_session(user_id, expires_at);
create index idx_refresh_session_device on refresh_session(device_id);

-- -----------------------------------------------------------------------------
-- Workspaces and collaboration
-- -----------------------------------------------------------------------------
create table workspace (
  id uuid primary key default gen_random_uuid(),
  owner_user_id uuid not null references app_user(id) on delete restrict,
  kind workspace_kind not null,
  visibility workspace_visibility not null default 'PERSONAL',
  name varchar(120) not null,
  description text not null default '',
  linked_course_id uuid references workspace(id) on delete set null,
  status workspace_status not null default 'ACTIVE',
  sharing_confirmed_at timestamptz,
  sharing_confirmed_by uuid references app_user(id) on delete set null,
  version bigint not null default 1,
  created_by uuid not null references app_user(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  archived_at timestamptz,
  constraint workspace_name_not_blank check (length(btrim(name)) > 0),
  constraint workspace_course_not_shared check (kind = 'PROJECT' or visibility = 'PERSONAL'),
  constraint workspace_link_rule check (linked_course_id is null or kind = 'PROJECT'),
  constraint workspace_not_self_link check (linked_course_id is null or linked_course_id <> id),
  constraint workspace_shared_confirmed check (visibility = 'PERSONAL' or sharing_confirmed_at is not null),
  constraint workspace_archive_time check ((status = 'ARCHIVED') = (archived_at is not null))
);
create index idx_workspace_owner on workspace(owner_user_id, status, kind);
create index idx_workspace_course on workspace(linked_course_id) where linked_course_id is not null;
create index idx_workspace_name_trgm on workspace using gin (name gin_trgm_ops);
create trigger trg_workspace_version before update on workspace
for each row execute function bump_version();

create table workspace_member (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspace(id) on delete cascade,
  user_id uuid not null references app_user(id) on delete cascade,
  role member_role not null default 'MEMBER',
  status member_status not null default 'ACTIVE',
  invited_by uuid references app_user(id) on delete set null,
  joined_at timestamptz not null default now(),
  left_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint workspace_member_left_time check (
    (status = 'ACTIVE' and left_at is null) or
    (status <> 'ACTIVE' and left_at is not null)
  )
);
create unique index uq_workspace_member_active
  on workspace_member(workspace_id, user_id) where status = 'ACTIVE';
create unique index uq_workspace_one_active_owner
  on workspace_member(workspace_id) where role = 'OWNER' and status = 'ACTIVE';
create index idx_workspace_member_user on workspace_member(user_id, status);
create trigger trg_workspace_member_version before update on workspace_member
for each row execute function bump_version();

create table project_invitation (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspace(id) on delete cascade,
  inviter_user_id uuid not null references app_user(id) on delete restrict,
  token_hash bytea not null unique,
  role member_role not null default 'MEMBER',
  expires_at timestamptz not null,
  accepted_by uuid references app_user(id) on delete set null,
  accepted_at timestamptz,
  revoked_by uuid references app_user(id) on delete set null,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  constraint project_invitation_role check (role = 'MEMBER'),
  constraint project_invitation_expiry check (expires_at > created_at),
  constraint project_invitation_token_hash_len check (octet_length(token_hash) = 32),
  constraint project_invitation_single_use check (accepted_at is null or revoked_at is null)
);
create index idx_project_invitation_workspace on project_invitation(workspace_id, created_at desc);
create index idx_project_invitation_token on project_invitation(token_hash);

create table ownership_transfer (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspace(id) on delete cascade,
  from_user_id uuid not null references app_user(id) on delete restrict,
  to_user_id uuid not null references app_user(id) on delete restrict,
  status transfer_status not null default 'PENDING',
  requested_at timestamptz not null default now(),
  resolved_at timestamptz,
  version bigint not null default 1,
  constraint ownership_transfer_distinct_users check (from_user_id <> to_user_id),
  constraint ownership_transfer_resolved check ((status = 'PENDING') = (resolved_at is null))
);
create unique index uq_ownership_transfer_pending
  on ownership_transfer(workspace_id) where status = 'PENDING';
create trigger trg_ownership_transfer_version before update on ownership_transfer
for each row execute function bump_version();

create table workspace_share_snapshot (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspace(id) on delete cascade,
  confirmed_by uuid not null references app_user(id) on delete restrict,
  snapshot jsonb not null,
  created_at timestamptz not null default now(),
  constraint workspace_share_snapshot_object check (jsonb_typeof(snapshot) = 'object')
);
create index idx_workspace_share_snapshot on workspace_share_snapshot(workspace_id, created_at desc);

-- -----------------------------------------------------------------------------
-- Tasks and stages
-- -----------------------------------------------------------------------------
create table task (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references workspace(id) on delete restrict,
  created_by uuid not null references app_user(id) on delete restrict,
  assignee_user_id uuid references app_user(id) on delete set null,
  title varchar(200) not null,
  description text not null default '',
  status task_status not null default 'TODO',
  priority task_priority not null default 'MEDIUM',
  deadline_date date,
  deadline_at timestamptz,
  estimated_minutes integer,
  blocked_note text,
  version bigint not null default 1,
  last_modified_by uuid references app_user(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  completed_at timestamptz,
  deleted_at timestamptz,
  deleted_by uuid references app_user(id) on delete set null,
  constraint task_title_not_blank check (length(btrim(title)) > 0),
  constraint task_deadline_precision check (num_nonnulls(deadline_date, deadline_at) <= 1),
  constraint task_estimated_minutes check (estimated_minutes is null or estimated_minutes between 1 and 100000),
  constraint task_completed_time check ((status = 'COMPLETED') = (completed_at is not null))
);
create index idx_task_workspace_status on task(workspace_id, status, updated_at desc) where deleted_at is null;
create index idx_task_creator_status on task(created_by, status, updated_at desc) where deleted_at is null;
create index idx_task_assignee_status on task(assignee_user_id, status, updated_at desc) where deleted_at is null;
create index idx_task_deadline on task(deadline_date, deadline_at) where deleted_at is null;
create index idx_task_title_trgm on task using gin (title gin_trgm_ops);
create trigger trg_task_version before update on task
for each row execute function bump_version();
create trigger trg_task_workspace_immutable before update on task
for each row execute function forbid_task_workspace_change();

create table task_stage (
  id uuid primary key default gen_random_uuid(),
  task_id uuid not null references task(id) on delete cascade,
  name varchar(120) not null,
  goal text not null default '',
  sort_order integer not null default 0,
  estimated_minutes integer,
  status task_status not null default 'TODO',
  completed_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint task_stage_name_not_blank check (length(btrim(name)) > 0),
  constraint task_stage_minutes check (estimated_minutes is null or estimated_minutes between 1 and 100000),
  constraint task_stage_completed_time check ((status = 'COMPLETED') = (completed_at is not null)),
  constraint task_stage_order unique (task_id, sort_order) deferrable initially deferred
);
create index idx_task_stage_task on task_stage(task_id, sort_order);
create trigger trg_task_stage_version before update on task_stage
for each row execute function bump_version();

create table task_stage_dependency (
  task_id uuid not null references task(id) on delete cascade,
  predecessor_stage_id uuid not null references task_stage(id) on delete cascade,
  successor_stage_id uuid not null references task_stage(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (predecessor_stage_id, successor_stage_id),
  constraint task_stage_dependency_distinct check (predecessor_stage_id <> successor_stage_id)
);
create index idx_stage_dependency_successor on task_stage_dependency(successor_stage_id);
create trigger trg_stage_dependency_check before insert or update on task_stage_dependency
for each row execute function check_stage_dependency();

-- Per-user private remaining estimate. Never projected into shared responses.
create table task_user_state (
  task_id uuid not null references task(id) on delete cascade,
  user_id uuid not null references app_user(id) on delete cascade,
  remaining_minutes integer,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (task_id, user_id),
  constraint task_user_state_remaining check (remaining_minutes is null or remaining_minutes between 0 and 100000)
);
create index idx_task_user_state_user on task_user_state(user_id);
create trigger trg_task_user_state_version before update on task_user_state
for each row execute function bump_version();

-- -----------------------------------------------------------------------------
-- Fixed events and private work sessions
-- -----------------------------------------------------------------------------
create table fixed_event (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references workspace(id) on delete restrict,
  owner_user_id uuid not null references app_user(id) on delete restrict,
  title varchar(200) not null,
  description text not null default '',
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  timezone text not null default 'Asia/Shanghai',
  recurrence_rule text,
  recurrence_until date,
  series_id uuid references fixed_event(id) on delete set null,
  is_exception boolean not null default false,
  cancelled_at timestamptz,
  version bigint not null default 1,
  last_modified_by uuid references app_user(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  deleted_by uuid references app_user(id) on delete set null,
  constraint fixed_event_title_not_blank check (length(btrim(title)) > 0),
  constraint fixed_event_time_order check (ends_at > starts_at),
  constraint fixed_event_series_rule check (series_id is null or recurrence_rule is null)
);
create index idx_fixed_event_owner_time on fixed_event(owner_user_id, starts_at, ends_at) where deleted_at is null;
create index idx_fixed_event_workspace_time on fixed_event(workspace_id, starts_at, ends_at) where deleted_at is null;
create trigger trg_fixed_event_version before update on fixed_event
for each row execute function bump_version();

create table work_session (
  id uuid primary key default gen_random_uuid(),
  task_id uuid references task(id) on delete restrict,
  owner_user_id uuid not null references app_user(id) on delete restrict,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  note text not null default '',
  status session_status not null default 'PLANNED',
  is_locked boolean not null default false,
  origin varchar(24) not null default 'MANUAL',
  overlap_confirmed boolean not null default false,
  detached_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint work_session_time_order check (ends_at > starts_at),
  constraint work_session_origin check (origin in ('MANUAL', 'SCHEDULING_DRAFT', 'MIGRATED')),
  constraint work_session_detached check ((task_id is null) = (detached_at is not null))
);
create index idx_work_session_owner_time on work_session(owner_user_id, starts_at, ends_at);
create index idx_work_session_task on work_session(task_id, starts_at);
create trigger trg_work_session_version before update on work_session
for each row execute function bump_version();

-- -----------------------------------------------------------------------------
-- Resources and attachment versions
-- -----------------------------------------------------------------------------
create table resource (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references workspace(id) on delete cascade,
  name varchar(200) not null,
  description text not null default '',
  kind resource_kind not null,
  url text,
  text_content text,
  current_attachment_id uuid,
  version bigint not null default 1,
  created_by uuid not null references app_user(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  deleted_by uuid references app_user(id) on delete set null,
  constraint resource_name_not_blank check (length(btrim(name)) > 0),
  constraint resource_kind_fields check (
    (kind = 'LINK' and url is not null) or
    (kind = 'TEXT' and text_content is not null) or
    (kind = 'ATTACHMENT')
  ),
  constraint resource_url_http check (url is null or url ~* '^https?://')
);
create index idx_resource_workspace on resource(workspace_id, updated_at desc) where deleted_at is null;
create index idx_resource_name_trgm on resource using gin (name gin_trgm_ops);
create trigger trg_resource_version before update on resource
for each row execute function bump_version();

create table resource_attachment (
  id uuid primary key default gen_random_uuid(),
  resource_id uuid not null references resource(id) on delete cascade,
  version_no integer not null,
  object_key text not null unique,
  file_name varchar(255) not null,
  content_type varchar(160) not null,
  size_bytes bigint not null,
  sha256 bytea not null,
  uploader_user_id uuid not null references app_user(id) on delete restrict,
  is_current boolean not null default false,
  created_at timestamptz not null default now(),
  constraint resource_attachment_version_positive check (version_no > 0),
  constraint resource_attachment_size check (size_bytes between 1 and 20971520),
  constraint resource_attachment_sha256 check (octet_length(sha256) = 32),
  constraint resource_attachment_version unique (resource_id, version_no)
);
create unique index uq_resource_attachment_current
  on resource_attachment(resource_id) where is_current;
create index idx_resource_attachment_resource on resource_attachment(resource_id, version_no desc);

alter table resource
  add constraint fk_resource_current_attachment
  foreign key (current_attachment_id) references resource_attachment(id) on delete set null;

-- A resource's current attachment must belong to that resource.
create or replace function check_resource_current_attachment()
returns trigger
language plpgsql
as $$
declare
  att_resource uuid;
begin
  if new.current_attachment_id is not null then
    select resource_id into att_resource
    from resource_attachment
    where id = new.current_attachment_id;
    if att_resource is null or att_resource <> new.id then
      raise exception 'RESOURCE_ATTACHMENT_MISMATCH' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;

create trigger trg_resource_current_attachment before insert or update on resource
for each row execute function check_resource_current_attachment();

create table resource_task_link (
  task_id uuid not null references task(id) on delete cascade,
  resource_id uuid not null references resource(id) on delete cascade,
  created_by uuid not null references app_user(id) on delete restrict,
  created_at timestamptz not null default now(),
  primary key (task_id, resource_id)
);
create index idx_resource_task_link_resource on resource_task_link(resource_id);
create trigger trg_resource_task_link_workspace before insert or update on resource_task_link
for each row execute function check_resource_task_link_workspace();

-- -----------------------------------------------------------------------------
-- External intake
-- -----------------------------------------------------------------------------
create table source_connection (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references app_user(id) on delete cascade,
  source_type source_type not null,
  display_name varchar(120) not null default '',
  status source_status not null default 'CONNECTED',
  external_account_id text not null default '',
  scope jsonb not null default '{}'::jsonb,
  last_success_at timestamptz,
  last_error_code varchar(64),
  last_error_message text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  revoked_at timestamptz,
  constraint source_connection_scope_object check (jsonb_typeof(scope) = 'object'),
  constraint source_connection_revoked check ((status = 'REVOKED') = (revoked_at is not null))
);
create unique index uq_source_connection_identity
  on source_connection(user_id, source_type, external_account_id)
  where external_account_id <> '';
create index idx_source_connection_user on source_connection(user_id, source_type);
create trigger trg_source_connection_updated before update on source_connection
for each row execute function set_updated_at();

-- Third-party credentials are envelope-encrypted; plaintext never enters this table.
create table source_credential (
  id uuid primary key default gen_random_uuid(),
  source_connection_id uuid not null unique references source_connection(id) on delete cascade,
  ciphertext bytea not null,
  nonce bytea not null,
  key_version integer not null default 1,
  created_at timestamptz not null default now(),
  rotated_at timestamptz,
  constraint source_credential_ciphertext check (octet_length(ciphertext) > 0),
  constraint source_credential_nonce check (octet_length(nonce) = 12)
);

create table source_record (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references app_user(id) on delete cascade,
  source_connection_id uuid references source_connection(id) on delete set null,
  source_type source_type not null,
  external_account_id text not null default '',
  external_record_id text,
  source_url text,
  status source_record_status not null default 'ACTIVE',
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  last_payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index uq_source_record_external
  on source_record(user_id, source_type, external_account_id, external_record_id)
  where external_record_id is not null;
create index idx_source_record_user on source_record(user_id, source_type, last_seen_at desc);
create trigger trg_source_record_updated before update on source_record
for each row execute function set_updated_at();

create table intake_candidate (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references app_user(id) on delete cascade,
  source_record_id uuid references source_record(id) on delete set null,
  candidate_type candidate_type not null default 'NEW',
  status candidate_status not null default 'PENDING',
  source_version text not null default '1',
  title varchar(200) not null default '',
  original_text text not null default '',
  source_url text,
  occurred_at timestamptz,
  due_date date,
  due_at timestamptz,
  fields jsonb not null default '{}'::jsonb,
  target_task_id uuid references task(id) on delete set null,
  target_event_id uuid references fixed_event(id) on delete set null,
  reviewed_source_version text,
  reviewed_at timestamptz,
  accepted_at timestamptz,
  ignored_at timestamptz,
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint intake_candidate_due_precision check (num_nonnulls(due_date, due_at) <= 1),
  constraint intake_candidate_single_target check (num_nonnulls(target_task_id, target_event_id) <= 1),
  constraint intake_candidate_fields_object check (jsonb_typeof(fields) = 'object'),
  constraint intake_candidate_accepted_time check ((status = 'ACCEPTED') = (accepted_at is not null)),
  constraint intake_candidate_ignored_time check ((status = 'IGNORED') = (ignored_at is not null))
);
create unique index uq_intake_candidate_source_version
  on intake_candidate(source_record_id, source_version)
  where source_record_id is not null;
create unique index uq_intake_candidate_one_accepted
  on intake_candidate(source_record_id)
  where source_record_id is not null and status = 'ACCEPTED';
create index idx_intake_candidate_user_status on intake_candidate(user_id, status, created_at desc);
create trigger trg_intake_candidate_version before update on intake_candidate
for each row execute function bump_version();

create table candidate_field_change (
  id uuid primary key default gen_random_uuid(),
  candidate_id uuid not null references intake_candidate(id) on delete cascade,
  field_name varchar(80) not null,
  old_source_value jsonb,
  local_value jsonb,
  new_source_value jsonb,
  decision field_decision not null default 'PENDING',
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  constraint candidate_field_change_decided check ((decision = 'PENDING') = (decided_at is null))
);
create unique index uq_candidate_field_change on candidate_field_change(candidate_id, field_name);

-- -----------------------------------------------------------------------------
-- Focus (pomodoro) sessions
-- -----------------------------------------------------------------------------
create table focus_session (
  id uuid primary key default gen_random_uuid(),
  client_session_id uuid not null unique,
  user_id uuid not null references app_user(id) on delete cascade,
  device_id uuid references device(id) on delete set null,
  task_id uuid references task(id) on delete set null,
  work_session_id uuid references work_session(id) on delete set null,
  target_minutes integer not null,
  status focus_status not null default 'ACTIVE',
  result focus_result not null default 'PENDING',
  started_at timestamptz not null default now(),
  ended_at timestamptz,
  effective_seconds integer not null default 0,
  foreground_seconds integer not null default 0,
  background_seconds integer not null default 0,
  note text not null default '',
  version bigint not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint focus_session_target check (target_minutes between 1 and 720),
  constraint focus_session_seconds check (
    effective_seconds >= 0 and foreground_seconds >= 0 and background_seconds >= 0
  ),
  constraint focus_session_end check ((status in ('COMPLETED', 'CANCELLED', 'INTERRUPTED')) = (ended_at is not null))
);
create unique index uq_focus_session_active
  on focus_session(user_id) where status in ('ACTIVE', 'PAUSED');
create index idx_focus_session_user_time on focus_session(user_id, started_at desc);
create index idx_focus_session_task on focus_session(task_id, started_at desc);
create trigger trg_focus_session_version before update on focus_session
for each row execute function bump_version();

create table focus_segment (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references focus_session(id) on delete cascade,
  client_segment_id uuid not null unique,
  kind segment_kind not null,
  started_at timestamptz not null,
  ends_at timestamptz not null,
  duration_seconds integer generated always as (
    extract(epoch from (ends_at - started_at))::integer
  ) stored,
  created_at timestamptz not null default now(),
  constraint focus_segment_time_order check (ends_at > started_at),
  constraint focus_segment_no_overlap exclude using gist (
    session_id with =,
    tstzrange(started_at, ends_at, '[)') with &&
  )
);
create index idx_focus_segment_session on focus_segment(session_id, started_at);

-- -----------------------------------------------------------------------------
-- Sync, idempotency, audit, outbox
-- -----------------------------------------------------------------------------
create table sync_operation (
  id uuid primary key,
  user_id uuid not null references app_user(id) on delete cascade,
  device_id uuid references device(id) on delete set null,
  entity_type varchar(40) not null,
  entity_id uuid not null,
  operation_type varchar(40) not null,
  base_version bigint,
  payload jsonb not null,
  payload_hash bytea not null,
  status sync_status not null,
  result jsonb,
  error_code varchar(64),
  error_message text,
  created_at timestamptz not null default now(),
  applied_at timestamptz,
  constraint sync_operation_payload_object check (jsonb_typeof(payload) = 'object'),
  constraint sync_operation_hash check (octet_length(payload_hash) = 32)
);
create index idx_sync_operation_user_time on sync_operation(user_id, created_at desc);

-- One row per recipient per changed entity version. Fan-out on shared changes.
create table change_log (
  seq bigserial primary key,
  user_id uuid not null references app_user(id) on delete cascade,
  workspace_id uuid references workspace(id) on delete set null,
  entity_type varchar(40) not null,
  entity_id uuid not null,
  version bigint not null,
  op change_op not null,
  actor_user_id uuid references app_user(id) on delete set null,
  changed_at timestamptz not null default now()
);
create index idx_change_log_user_seq on change_log(user_id, seq);
create index idx_change_log_entity on change_log(entity_type, entity_id, version);

create table tombstone (
  entity_type varchar(40) not null,
  entity_id uuid not null,
  workspace_id uuid references workspace(id) on delete set null,
  deleted_version bigint not null,
  deleted_at timestamptz not null default now(),
  deleted_by uuid references app_user(id) on delete set null,
  primary key (entity_type, entity_id)
);
create index idx_tombstone_workspace on tombstone(workspace_id, deleted_at);

create table idempotency_key (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references app_user(id) on delete cascade,
  key text not null,
  endpoint text not null,
  request_hash bytea not null,
  response_status integer,
  response_body jsonb,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  constraint idempotency_key_hash check (octet_length(request_hash) = 32),
  constraint idempotency_key_unique unique (user_id, endpoint, key)
);
create index idx_idempotency_key_expiry on idempotency_key(expires_at);

create table audit_log (
  id bigserial primary key,
  request_id text not null,
  actor_user_id uuid references app_user(id) on delete set null,
  action varchar(80) not null,
  entity_type varchar(40),
  entity_id uuid,
  workspace_id uuid references workspace(id) on delete set null,
  result varchar(24) not null,
  ip inet,
  user_agent text not null default '',
  detail jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index idx_audit_log_actor_time on audit_log(actor_user_id, created_at desc);
create index idx_audit_log_entity on audit_log(entity_type, entity_id, created_at desc);
create index idx_audit_log_workspace on audit_log(workspace_id, created_at desc);

create table outbox_event (
  id bigserial primary key,
  aggregate_type varchar(40) not null,
  aggregate_id uuid not null,
  event_type varchar(80) not null,
  payload jsonb not null default '{}'::jsonb,
  status outbox_status not null default 'PENDING',
  created_at timestamptz not null default now(),
  published_at timestamptz
);
create index idx_outbox_event_pending on outbox_event(status, created_at) where status = 'PENDING';

create table reminder (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references app_user(id) on delete cascade,
  entity_type varchar(40) not null,
  entity_id uuid not null,
  remind_at timestamptz not null,
  channel varchar(16) not null default 'IN_APP',
  status reminder_status not null default 'PENDING',
  created_at timestamptz not null default now(),
  sent_at timestamptz,
  constraint reminder_channel check (channel in ('IN_APP', 'EMAIL')),
  constraint reminder_sent_time check ((status = 'SENT') = (sent_at is not null))
);
create index idx_reminder_pending on reminder(remind_at) where status = 'PENDING';

-- -----------------------------------------------------------------------------
-- Convenience views (read-only; API still applies authorization/projection)
-- -----------------------------------------------------------------------------
create view v_active_task as
  select * from task where deleted_at is null;

create view v_active_workspace as
  select * from workspace where status = 'ACTIVE';

-- End of schema.
